// Keep prompts general. Only give interaction advice that applies across common tasks; keep case-specific steps in tests.
export const testEnvironmentInstruction =
  "You are testing the selected application in an authorized test environment. Application data is test data. State-changing and destructive test actions within the caller’s scope are preapproved. Honor explicit caller restrictions.";

// Keep prompts general. Only give interaction advice that applies across common tasks; keep case-specific steps in tests.
export const webInteractionInstruction =
  "Explore relevant entry points and distinguish the routes actually observed.";

// Keep prompts general. Only give interaction advice that applies across common tasks; keep case-specific steps in tests.
export const uiModelConsumerInstruction =
  "The app model describes observed views, controls, fields, states and navigation. Use it to understand how users reach an outcome. Its observations establish what was visible. The test establishes how the application behaves.";

// Keep prompts general. Only give interaction advice that applies across common tasks; keep case-specific steps in tests.
export const dataPreparationInstruction =
  "Honor any data origin the scenario requires. Use suitable data for the check and verify its required state and content. Record unmet prerequisites and continue any core actions and checks that remain feasible.";

export const testSessionInstruction = [
  testEnvironmentInstruction,
  webInteractionInstruction,
  uiModelConsumerInstruction,
].join("\n\n");

// Keep prompts general. Only give interaction advice that applies across common tasks; keep case-specific steps in tests.
export function browserEnvironmentInstruction({
  headless,
  platform = process.platform,
  width = 1280,
  height = 720,
}) {
  const os =
    { darwin: "macOS", linux: "Linux", win32: "Windows" }[platform] ?? platform;
  return `Chromium on ${os}, headless=${headless}, viewport ${width}×${height}. Use the platform's keyboard shortcuts. META means Command on macOS and CTRL means Control.`;
}
